import { describe, expect, test } from "vitest";
import { planDirectCharacterWrites } from "../../../src/core/chatDirectWrite";
import { emptyCharacter, type Character } from "../../../src/models/character";
import type { PlotCharacterPlan } from "../../../src/core/plotCharacterSync";
import type { PendingUpdate } from "../../../src/core/pendingUpdates";

/**
 * 相談パネルから人物の資料へ**直接**書く（作者の裁定 J14、2026-09-26）。
 *
 * 突き合わせ（`buildPlotCharacterUpdates`）の結果のうち、何を直接書き、
 * 何を承認待ちへ回すかを決める。**実装ルール2を守る**：
 *
 * - `authorNotes`・`exportNote`・呼称などの欄は書き換えない（紹介文と食い違いの記録だけ）
 * - `autoGenerated: false` の人物は書かない（承認待ちへ回す）
 * - 既にある紹介文と食い違うときは、上書きせず食い違い（6.18）として残す
 */

function person(
  id: string,
  name: string,
  overrides: Partial<Character> = {}
): Character {
  return { ...emptyCharacter(id, name), ...overrides };
}

function plan(
  overrides: Partial<PlotCharacterPlan<PendingUpdate>>
): PlotCharacterPlan<PendingUpdate> {
  return {
    updates: [],
    creations: [],
    pendingOverlays: [],
    renames: [],
    skipped: [],
    ...overrides,
  };
}

describe("相談から人物へ直接書く計画", () => {
  test("紹介文が空の人物には、決まった紹介文を書く（ほかの欄は元のまま）", () => {
    const existing = person("char_001", "相馬誠", {
      summary: "",
      authorNotes: "作者のメモ",
      exportNote: "書き出し用",
    });
    const proposal = { ...structuredClone(existing), summary: "剣士。左利き" };

    const result = planDirectCharacterWrites(
      plan({ updates: [proposal] }),
      [existing],
      []
    );

    expect(result.writes).toHaveLength(1);
    const written = result.writes[0];
    expect(written.summary).toBe("剣士。左利き");
    expect(written.authorNotes).toBe("作者のメモ");
    expect(written.exportNote).toBe("書き出し用");
    expect(result.filled).toEqual(["相馬誠"]);
    expect(result.conflicted).toEqual([]);
  });

  test("案の側で作者の欄が変わっていても、書くのは紹介文だけ", () => {
    const existing = person("char_001", "相馬誠", {
      summary: "",
      authorNotes: "作者のメモ",
    });
    const proposal = {
      ...structuredClone(existing),
      summary: "剣士",
      authorNotes: "AIが書いたもの",
      exportNote: "AIが書いたもの",
    };

    const [written] = planDirectCharacterWrites(
      plan({ updates: [proposal] }),
      [existing],
      []
    ).writes;

    expect(written.authorNotes).toBe("作者のメモ");
    expect(written.exportNote).toBe(existing.exportNote);
  });

  test("既にある紹介文と食い違うなら上書きせず、食い違いとして残す", () => {
    const existing = person("char_001", "相馬誠", { summary: "弓使い" });
    const proposal = { ...structuredClone(existing), summary: "剣士" };

    const result = planDirectCharacterWrites(
      plan({ updates: [proposal] }),
      [existing],
      []
    );

    const [written] = result.writes;
    expect(written.summary).toBe("弓使い");
    const conflict = written.conflicts.find((item) => item.field === "summary");
    expect(conflict?.values).toEqual(["弓使い", "剣士"]);
    expect(result.conflicted).toEqual(["相馬誠"]);
    expect(result.filled).toEqual([]);
  });

  test("同じ食い違いを2度足さない", () => {
    const existing = person("char_001", "相馬誠", {
      summary: "弓使い",
      conflicts: [
        { field: "summary", values: ["弓使い", "剣士"], chapters: [], note: null },
      ],
    });
    const proposal = { ...structuredClone(existing), summary: "剣士" };

    const result = planDirectCharacterWrites(
      plan({ updates: [proposal] }),
      [existing],
      []
    );

    // 既に残してある食い違いなら、書くものが無い（ファイルに触らない）
    expect(result.writes).toEqual([]);
    expect(result.conflicted).toEqual([]);
  });

  test("作者が確定させた人物（autoGenerated: false）は書かず、承認待ちへ回す", () => {
    const existing = person("char_001", "相馬誠", {
      summary: "",
      autoGenerated: false,
    });
    const proposal = { ...structuredClone(existing), summary: "剣士" };

    const result = planDirectCharacterWrites(
      plan({ updates: [proposal] }),
      [existing],
      []
    );

    expect(result.writes).toEqual([]);
    expect(result.toPending.updates).toEqual([proposal]);
  });

  test("名前を直す案・承認待ちの案に重ねたものは、承認待ちへ回す", () => {
    const existing = person("char_001", "主人公");
    const overlay = {
      proposal: { kind: "update" } as unknown as PendingUpdate,
      character: existing,
    };
    const result = planDirectCharacterWrites(
      plan({ pendingOverlays: [overlay] }),
      [existing],
      []
    );
    expect(result.writes).toEqual([]);
    expect(result.toPending.pendingOverlays).toEqual([overlay]);
  });

  test("資料に居ない人は、番号を採って新しく作る", () => {
    const existing = person("char_003", "相馬誠");
    const result = planDirectCharacterWrites(
      plan({ creations: [{ name: "早瀬陸", summary: "幼なじみ" }] }),
      [existing],
      []
    );

    expect(result.creations).toHaveLength(1);
    expect(result.creations[0].name).toBe("早瀬陸");
    expect(result.creations[0].summary).toBe("幼なじみ");
    expect(result.creations[0].id).not.toBe("char_003");
    expect(result.creations[0].id).toMatch(/^char_\d+$/);
  });

  test("同じ名前の新規案が承認待ちにあれば、直接作らず承認待ちへ（同じ人が2人になる）", () => {
    const pendingCreation = person("pending", "早瀬陸");
    const result = planDirectCharacterWrites(
      plan({ creations: [{ name: "早瀬陸", summary: "幼なじみ" }] }),
      [],
      [pendingCreation]
    );

    expect(result.creations).toEqual([]);
    expect(result.toPending.creations).toEqual([
      { name: "早瀬陸", summary: "幼なじみ" },
    ]);
  });

  test("何も変わらない案（同じ紹介文）は書かない", () => {
    const existing = person("char_001", "相馬誠", { summary: "剣士" });
    const proposal = { ...structuredClone(existing), summary: "剣士" };
    const result = planDirectCharacterWrites(
      plan({ updates: [proposal] }),
      [existing],
      []
    );
    expect(result.writes).toEqual([]);
  });
});
